/** Root of the tree to draw: a branch carries children, a leaf carries none. */
export type Data = { name: string; children?: Data[] };

const MARGIN = { top: 20, right: 16, bottom: 20, left: 56 };
const ROW_HEIGHT = 16;
const DURATION = 400;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels that would leave the viewBox. */
const CHAR_WIDTH = 5.6;

type Point = { x: number; y: number };

interface TreeNode extends d3.HierarchyPointNode<Data> {
  id: string;
  /** Children hidden by a collapse, stashed so re-expanding restores the same subtree. */
  _children?: TreeNode[];
  /** Previous position, so entering marks grow out of the node that was clicked. */
  x0?: number;
  y0?: number;
}

type TreeLink = { source: Point; target: Point };

const diagonal = d3
  .linkHorizontal<TreeLink, Point>()
  .x((d) => d.y)
  .y((d) => d.x);

/** Collapse a link to a point, so it can enter from and exit to its parent. */
function pointLink(x: number, y: number): string | null {
  return diagonal({ source: { x, y }, target: { x, y } });
}

/** Vertical extent of the laid-out tree; it follows the visible node count, not the data. */
function extentOf(root: TreeNode) {
  let top = root.x;
  let bottom = root.x;
  root.eachBefore((node) => {
    if (node.x < top) top = node.x;
    if (node.x > bottom) bottom = node.x;
  });
  return { top, height: bottom - top + MARGIN.top + MARGIN.bottom };
}

export default function CollapsibleTree({
  data = d3Modules,
  width
}: {
  data?: Data;
  width: number;
}) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [version, setVersion] = useState(0);

  const root = useMemo(() => {
    const hierarchy = d3.hierarchy(data) as TreeNode;
    hierarchy.descendants().forEach((node, index) => {
      node.id = String(index);
      node._children = node.children;
      if (node.depth >= 1) node.children = undefined;
    });
    return hierarchy;
  }, [data]);

  const layout = useMemo(() => {
    const columnWidth = Math.max(48, (width - MARGIN.left - MARGIN.right) / (1 + root.height));
    return d3.tree<Data>().nodeSize([ROW_HEIGHT, columnWidth]);
  }, [root, width]);

  // A toggle mutates root in place, so the version counter is what re-derives the box.
  const box = useMemo(() => {
    layout(root);
    return extentOf(root);
  }, [layout, root, version]);

  useEffect(() => {
    const element = svgRef.current;
    if (!element) return;

    const svg = d3.select(element);
    // StrictMode runs this effect twice; without the clear the second run overlays a second tree.
    svg.selectAll('*').remove();

    const gLink = svg
      .append('g')
      .attr('fill', 'none')
      .attr('stroke', 'var(--line)')
      .attr('stroke-width', 1.5);
    const gNode = svg.append('g').attr('cursor', 'pointer');

    const rightEdge = width - MARGIN.left;
    const fits = (node: TreeNode) =>
      node.y + 8 + node.data.name.length * CHAR_WIDTH < rightEdge;

    function toggle(_event: PointerEvent, node: TreeNode) {
      node.children = node.children ? undefined : node._children;
      setVersion((previous) => previous + 1);
      update(node);
    }

    function update(source: TreeNode) {
      layout(root);
      const nodes = root.descendants().reverse();
      const links = root.links() as TreeLink[];
      const originX = source.x0 ?? source.x;
      const originY = source.y0 ?? source.y;

      const node = gNode
        .selectAll<SVGGElement, TreeNode>('g')
        .data(nodes, (d) => d.id)
        .join(
          (enter) => {
            const entered = enter
              .append('g')
              .attr('transform', `translate(${originY},${originX})`)
              .attr('fill-opacity', 0)
              .attr('stroke-opacity', 0)
              .on('click', toggle);
            entered
              .append('circle')
              .attr('r', 3)
              .attr('fill', (d) => (d._children ? 'var(--accent)' : 'var(--muted)'));
            entered
              .append('text')
              .attr('dy', '0.32em')
              .attr('x', (d) => (d._children ? -7 : 7))
              .attr('text-anchor', (d) => (d._children ? 'end' : 'start'))
              .attr('fill', 'var(--text)')
              .attr('stroke', 'var(--bg)')
              .attr('stroke-width', 3)
              .attr('stroke-linejoin', 'round')
              .attr('paint-order', 'stroke')
              .text((d) => (d._children || fits(d) ? d.data.name : ''));
            return entered;
          },
          undefined,
          (exit) => {
            exit
              .transition().duration(DURATION)
              .remove()
              .attr('transform', `translate(${source.y},${source.x})`)
              .attr('fill-opacity', 0)
              .attr('stroke-opacity', 0);
          }
        );

      node
        .transition().duration(DURATION)
        .attr('transform', (d) => `translate(${d.y},${d.x})`)
        .attr('fill-opacity', 1)
        .attr('stroke-opacity', 1);

      const link = gLink
        .selectAll<SVGPathElement, TreeLink>('path')
        .data(links, (d) => (d.target as TreeNode).id)
        .join(
          (enter) => enter.append('path').attr('d', pointLink(originX, originY)),
          undefined,
          (exit) => {
            exit
              .transition().duration(DURATION)
              .remove()
              .attr('d', pointLink(source.x, source.y));
          }
        );

      // The d interpolation here is shape morphing, which is why this chart lives behind a ref.
      link.transition().duration(DURATION).attr('d', (d) => diagonal(d));

      root.eachBefore((d) => {
        d.x0 = d.x;
        d.y0 = d.y;
      });
    }

    update(root);

    return () => {
      svg.interrupt();
      svg.selectAll('*').interrupt().remove();
    };
  }, [root, layout, width]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`${-MARGIN.left} ${box.top - MARGIN.top} ${width} ${box.height}`}
      width="100%"
      height={box.height}
      fontSize={FONT_SIZE}
      style={{ userSelect: 'none' }}
      role="img"
      aria-label="Collapsible tree of the D3 module taxonomy; click a node to expand or collapse it"
    />
  );
}
